figures.asymptoteSource:
import graph;
size(240,240);
pen p = currentpen;
draw(scale(2)*polygon(6));
pair O = (0,0);
pair A = dir(0);
pair B = dir(60);
pair M = (A+B)/2;
draw(O--A--B);
draw(O--M);
dot(O); dot(A); dot(B); dot(M);
label("$O$", O, SW);
label("$A$", A, SE);
label("$B$", B, NW);
label("$M$", M, E);
label("$a$", M/2, S);
label("$s$", (A+B)/2 + (0,0.3), NE);

import graph;
size(240,230);
pen p = currentpen;
pair O = (0,0);
draw(scale(2)*unitcircle, lightgray);
pair A = dir(150);
pair B = dir(30);
fill(O--arc(O,2,30,150)--cycle, white);
draw(scale(2)*unitcircle);
draw(O--A); draw(O--B);
dot(O);
label("$O$", O, SW);
label("$A$", A, W);
label("$B$", B, E);
label("$r$", A/2, NW);
label("$\theta$", O + (0,0.45), N);

size(240,260);
pen p = currentpen;
pair A = (-2,-1.1);
pair B = (2,-1.1);
pair C = (2,0.9);
pair D = (-2,0.9);
pair V = (0,2.4);
pair M = (0,0.9);
draw(A--B--C--D--cycle);
draw(V--A); draw(V--B); draw(V--C); draw(V--D);
draw(V--M, dashed);
dot(V); dot(M);
label("$V$", V, N);
label("$M$", M, E);
label("$h$", (0,1.65), W);
label("base", (0,-1.1), S);
